mapper.select:
SELECT id, location_id, state, fence_epoch, count_plan_id, version
FROM location_gate
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND location_id=#{locationId} FOR UPDATE

SELECT id, owner_id, location_id, sku_id, lot_id, quality_code, on_hand_qty, reserved_qty, free_execution_claim_qty, version
FROM stock_balance
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND owner_id=#{ownerId}
AND location_id=#{locationId}
AND sku_id=#{skuId}
AND lot_id=#{lotId}
AND quality_code=#{qualityCode} FOR UPDATE

SELECT id, owner_id, location_id, sku_id, lot_id, quality_code, on_hand_qty, reserved_qty, free_execution_claim_qty, version
FROM stock_balance
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{balanceId} FOR UPDATE

mapper.update:
UPDATE stock_balance
SET on_hand_qty=on_hand_qty+#{onHandDelta}, reserved_qty=reserved_qty+#{reservedDelta}, free_execution_claim_qty=free_execution_claim_qty+#{claimDelta}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{balanceId}
AND version=#{expectedVersion}
AND on_hand_qty+#{onHandDelta}>=0
AND reserved_qty+#{reservedDelta}>=0
AND free_execution_claim_qty+#{claimDelta}>=0
AND on_hand_qty+#{onHandDelta}>=reserved_qty+#{reservedDelta}+free_execution_claim_qty+#{claimDelta}

UPDATE stock_balance
SET reserved_qty=reserved_qty+#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{balanceId}
AND version=#{expectedVersion}
AND quality_code='GOOD'
AND on_hand_qty-reserved_qty-free_execution_claim_qty>=#{qty}

mapper.select:
SELECT id, allocation_id, attempt_id, request_digest, digest_version, state, xid, branch_id, action_name, route_epoch, execution_authorization_id, version
FROM reservation
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{reservationId} FOR UPDATE

SELECT COUNT(*)
FROM stock_ledger
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND operation_id=#{operationId}

mapper.update:
UPDATE reservation
SET state=#{toState}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{reservationId}
AND version=#{expectedVersion}
AND state=#{fromState}

mapper.select:
SELECT DISTINCT b.location_id
FROM reservation r JOIN reservation_line l ON l.enterprise_id=r.enterprise_id
AND l.warehouse_id=r.warehouse_id
AND l.reservation_id=r.id JOIN stock_balance b ON b.enterprise_id=r.enterprise_id
AND b.warehouse_id=r.warehouse_id
AND b.id=l.balance_id
WHERE r.enterprise_id=#{enterpriseId}
AND r.warehouse_id=#{warehouseId}
AND r.allocation_id=#{allocationId}
AND r.attempt_id=#{attemptId}
ORDER BY b.location_id

SELECT id, allocation_id, attempt_id, request_digest, digest_version, state, xid, branch_id, action_name, route_epoch, execution_authorization_id, version
FROM reservation
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND allocation_id=#{allocationId}
AND attempt_id=#{attemptId} FOR UPDATE

SELECT id, allocation_id, attempt_id, request_digest, digest_version, state, xid, branch_id, action_name, route_epoch, execution_authorization_id, version
FROM reservation
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND allocation_id=#{allocationId}
AND attempt_id=#{attemptId}

SELECT id, allocation_id, attempt_id, state, xid, updated_at
FROM reservation
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND state IN ('TRIED','CONFIRMED')
ORDER BY updated_at, id
LIMIT #{limit}

SELECT id, balance_id, requested_qty, remaining_qty, version
FROM reservation_line
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND reservation_id=#{reservationId}

mapper.update:
UPDATE reservation_line
SET released_qty=requested_qty, remaining_qty=0, picked_qty=0, inflight_qty=0, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}
AND remaining_qty=requested_qty
AND consumed_qty=0
AND released_qty=0

UPDATE reservation_line
SET balance_id=#{targetBalanceId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND balance_id=#{sourceBalanceId}
AND remaining_qty>0

mapper.select:
SELECT id, reservation_id, parent_line_id, order_line_id, balance_id, requested_qty, remaining_qty, picked_qty, consumed_qty, released_qty, version
FROM reservation_line
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND reservation_id=#{reservationId}
AND balance_id=#{balanceId}
AND remaining_qty>0
ORDER BY id
LIMIT 1 FOR UPDATE

mapper.update:
UPDATE reservation_line
SET requested_qty=requested_qty-#{qty}, remaining_qty=remaining_qty-#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}
AND remaining_qty>=#{qty}
AND remaining_qty=requested_qty-consumed_qty-released_qty

UPDATE reservation_line
SET remaining_qty=remaining_qty-#{qty}, consumed_qty=consumed_qty+#{qty}, picked_qty=picked_qty-#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}
AND remaining_qty>=#{qty}
AND picked_qty>=#{qty}

UPDATE reservation_line
SET released_qty=released_qty+remaining_qty, remaining_qty=0, picked_qty=0, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}
AND remaining_qty>0
AND remaining_qty=#{expected}
